INSERT INTO changelog (title, body, created_at) VALUES ('Продукти і Розвиток', 'Новий пункт меню «Продукти» (під «Рекламою»): паспорт кожного нашого продукту — програми (CRM, боти), набори-промпти, послуги. У паспорті: що це, як працює, фічі, з чого складається, посилання, плюси/мінуси, клієнти, які користуються; «Знання» — що ламалось і як виправили, інтеграції, юридичне/доступи/платежі, уроки (щоб не наступати вдруге); хроніка і план.
Як додати продукт: «Промпт: описати нову програму» → встав у Claude Code в репозиторії → він видасть [CLIENT-OPS:ПРОДУКТ] → встав у «Вставити витяжку» (або кинь Джері) — паспорт заповниться сам. Для існуючого продукту — «Промпт для Claude Code» на його сторінці: там увесь паспорт, наприкінці «витяжка» оновлює його.
Перший продукт — «Client Ops Connect»: набір інструкцій, який підключає будь-яку нашу програму до системи (помилки, відгуки, релізи, а для CRM/ботів — ліди і продажі). Продукт → «Звʼязок»: адреса і секрет для програми, події видно там; помилка/відгук → тобі в Telegram (тумблер).
«База знань» тепер «Розвиток»: хто ми, позиціонування, що надаємо, наш підхід, куди рухаємось, головне зараз + план розвитку (зараз/далі/потім), рішення, уроки, ідеї. Старі інструкції — вкладка «Інструкції». Джері бачить і розвиток, і продукти в кожній розмові.', datetime('now'));
